const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let S=null,collection=[],foundEvents=[];try{collection=JSON.parse(localStorage.getItem('island-v3-endings')||'[]')}catch{};
function topPage(){window.scrollTo({top:0,behavior:'smooth'})}function modal(html){$('#modalbody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}function closeModal(){$('#modal').close()}
function home(){if(S&&S.phase!=='result'){modal('<span class="eyebrow">RESTART VOYAGE</span><h2>지도를 처음부터 펼칠까요?</h2><p>현재 공연은 초기화됩니다. 발견한 엔딩은 이 브라우저에 남습니다.</p><button class="primary" onclick="S=null;closeModal();render();topPage()">새 항해 시작하기 ↗</button>');return}S=null;render();topPage()}
function start(){S=Game.fresh($('#player').value.trim());render();topPage()}
function act(fn,...args){const ok=Game[fn](S,...args);if(!ok){modal('<h2>지금 선택하기 어려운 구성입니다.</h2><p>남은 시간·예산·체력 또는 현재 준비 단계를 확인해주세요. 다른 구성을 고르거나 규모를 줄일 수 있습니다.</p>');return}rememberEvents();if(S.phase==='result')remember();render();topPage()}
try{foundEvents=JSON.parse(localStorage.getItem('island-v5-events')||'[]')}catch{};
function rememberEvents(){if(!S)return;foundEvents=[...new Set(foundEvents.concat(S.hiddenSeen||[]))];try{localStorage.setItem('island-v5-events',JSON.stringify(foundEvents))}catch{}}
function remember(){rememberEvents();if(!collection.includes(S.final)){collection.push(S.final);try{localStorage.setItem('island-v3-endings',JSON.stringify(collection))}catch{}}}
function help(){modal(`<span class="eyebrow">HOW TO SAIL</span><h2>섬에 공연을 세우는 방법</h2><ol><li>오프닝 다시!를 포함해 기본 10곡을 구성한다. 나머지 9곡은 네 후보 중 고른다.</li><li>신곡 공개와 특별 무대는 따로 선택한다. 추가할수록 준비와 체력 부담이 늘어난다.</li><li>Art·Performance·Music·Technic의 의견을 조율하고, 합주·동선·기술을 점검한다.</li><li>최종 점검에서 위험을 확인한다. 축소·보완 기회는 두 번이다.</li><li>공연 중 네 파트의 체력과 시간에 맞게 진행·축약·종료를 결정한다.</li></ol><p><b>기획 실패:</b> 전원 만족도 60 이하. <b>준비 실패:</b> 최종 필수 점검에 심각한 문제가 두 개 이상 남음. 두 조건은 별개이다.</p><p><b>추가 앙코르:</b> 네 명 각각 만족도 75 이상, 관객 80 이상, 해당 곡 무대 완성도 65 이상, 전원 체력·공연 시간 충족. 미연주 곡 중 고른다.</p><p><b>특별 이벤트:</b> 관객 만족도 90 이상이며 한 명 이상 체력 0이면, 퇴장하지 않은 팬들의 앵콜 요청에 응답하는 마지막 선택이 등장합니다.</p><p>준비 시간은 125, 기본 준비도는 50에서 시작한다. 휴식은 두 번(체력 +8, +4 / 각 3분), 관객 후렴은 한 번이다. 곡과 무관하게 챌린지 코너를 진행하며, 공연 중 돌발 상황 세 번에는 회복과 수습 선택지가 있다. 짧은 버전도 부담을 전부 없애지는 않는다.</p><p class="fine">난이도는 실제 연주 실력 평가가 아닌 게임용 잠정 수치이다. 앨범 크레딧과 게임의 공연 버전은 구분한다. 새로고침 시 현재 공연은 초기화되고 엔딩 수집만 남는다.</p>`)}
function sourceLink(key){const x=SOURCES[key];return x?`<a href="${esc(x[1])}" target="_blank" rel="noopener noreferrer">${x[0]} ↗</a>`:''}
function archive(){modal(`<span class="eyebrow">THE MEMORY ARCHIVE</span><h2>이전의 섬에서 가져온 것들.</h2><img class="archiveposter" src="assets/first-landing.webp" alt="2021년 First Landing 첫 공연 포스터 전체"><p>현재 화면은 2021년 First Landing의 지도에서 착안한 팬 창작 항해이다. 원본의 연도·공연 정보와 이번 게임의 설정을 구분한다.</p><div class="archiveitems"><h3>게임의 폰트</h3><p>기본 UI는 SUIT, 예찬은 Gaegu, 상엽은 Gamja Flower, 원상은 Single Day, 광일은 Hi Melody를 사용한다. 멤버별 폰트는 게임의 시각적 설정이며 실제 필체를 재현하지 않는다.</p><p><a href="assets/SUIT-LICENSE.txt" target="_blank">SUIT 라이선스</a> · <a href="https://github.com/google/fonts" target="_blank" rel="noopener noreferrer">손글씨 폰트 출처</a></p><h3>확인된 특별 무대</h3>${['pass','caprice','blind','line','encore'].map(sourceLink).join('')}<h3>추가 확인이 필요한 자료</h3><p>지브리 Medley의 공연 시점과 구성, 이번 앙콘의 멤버별 편지 전문은 미확인이다. 실제 발언·공식 재현인 것처럼 수록하지 않았다.</p><h3>곡 목록에서 바로잡은 점</h3><p>‘충분히 잘하고 있어’는 제외하고 확인된 ‘충분히’를 사용한다. ‘선물’은 LUCY 원곡 목록에서 제외한다. ‘해가뜨는밤’은 BLUE 수록 LUCY 곡이며, 게임에서는 상엽 보컬 중심 무대로 분류한다. Run To You 역시 상엽의 보컬·호흡 중심으로 설명한다. ‘내 쓸쓸함은 차갑지 않아요’는 LUCY 발매 명의를 보존하되 예찬 솔로 가창 무대로 편성한다.</p><h3>챌린지 참고 자료</h3>${CHALLENGES.map(x=>sourceLink(x.source)).join('')}<p class="fine">현재 유행 순위를 의미하지 않는 선택용 레퍼토리 / 난도와 체력은 게임용 수치</p><h3>음원·곡 분류 근거</h3>${Object.keys(SOURCES).filter(k=>!['pass','caprice','blind','line','encore',...CHALLENGES.map(x=>x.source)].includes(k)).map(sourceLink).join('')}</div><p class="fine">발매 명의·곡 존재 여부는 자료를 확인하였다. 파트별 점수와 체력은 잠정 게임 수치이며, 실제 Live 버전별 분석이 완료된 것으로 표시하지 않는다.</p>`)}
function album(){modal(`<span class="eyebrow">YOUR VOYAGE COLLECTION / ${collection.length} OF ${Object.keys(Game.ENDINGS).length}</span><h2>돌아온 섬의 기록.</h2><div class="endingcollection">${Object.entries(Game.ENDINGS).map(([k,v])=>`<div><span>${collection.includes(k)?'✦':'◇'}</span><b>${collection.includes(k)?v[0]:'아직 도착하지 않은 이야기'}</b></div>`).join('')}</div><h3 class="collectionsubtitle">숨은 항해 기록 · ${foundEvents.length}/3</h3><div class="endingcollection">${Object.entries(HIDDEN_EVENTS).map(([k,e])=>`<div><span>${foundEvents.includes(k)?'✦':'◇'}</span><b>${foundEvents.includes(k)?e.title:'아직 펼치지 않은 장면'}</b></div>`).join('')}</div>`)}
function render(){if(!S){$('#app').innerHTML=landing();return}if(S.phase==='result'){$('#app').innerHTML=result();return}const f=Game.step(S),stop=S.phase==='prep'?f.stop:['live','incident'].includes(S.phase)?4:5;$('#app').innerHTML=`<div class="voyagebar"><div><span class="eyebrow">CHAPTER 0${stop+1} / ${STOPS[stop].en}</span><h1>${STOPS[stop].name}</h1><p>${STOPS[stop].note}</p></div><span class="namebadge">${esc(S.name)}의 항해 일지</span></div><div class="journeygrid"><aside class="journeyside">${mapView(stop)}${status()}</aside><section class="workspace">${S.feedback?`<div class="feedback" role="status">${esc(S.feedback)}</div>`:''}${S.phase==='prep'?prep():S.phase==='incident'?incidentView():S.phase==='live'?live():S.phase==='farewell'?farewellView():encoreView()}</section></div>`}
function landing(){return `<section class="landing"><div class="herotext"><span class="eyebrow">A MAP OF OUR MOMENTS · LUCY ENCORE</span><h1>흩어졌던 순간들이<br>다시, <i>섬</i>으로.</h1><div class="herorule"></div><h2>루시 아일랜드 앙코르 콘서트 기획하기!</h2><p>처음 울릴 선율부터, 끝내기 아쉬운 마지막 인사까지.<br>네 사람의 다른 생각을 모아<br>우리가 다시 돌아올 공연을 만들어주세요.</p><div class="entry"><label class="sr-only" for="player">기획 담당자 이름</label><input id="player" maxlength="16" placeholder="기획 담당자 이름"><button class="primary" onclick="start()">항해 시작하기 <span>↗</span></button></div><div class="herometa"><span>다시! + 선택 9곡</span><span>선택으로 달라지는 무대</span><span>14개의 엔딩</span></div></div><div class="heromap"><div class="maplabel">LUCY ISLAND <small>YOUR OWN CONCERT MAP</small></div><img src="assets/voyage-map.webp" alt="First Landing의 선화로 그려진 루시 섬 지도"><span class="compassrose">N<br>✦<br>S</span><div class="mapquote">모두 다른 곳에서 출발했지만,<br>오늘은 같은 섬에서 만납니다.</div><span class="mapstamp">ADMIT ONE<br><b>ENCORE</b></span></div></section><section class="introstrip"><div><span>01 / CHOOSE</span><h3>한 곡을 고르는 마음.</h3><p>귀여운 이벤트, 특별 연주, 목소리에 집중하는 시간.</p></div><div><span>02 / PREPARE</span><h3>모두 담을 수는 없으니까.</h3><p>다른 요구를 조율하고, 필요한 준비를 남깁니다.</p></div><div><span>03 / REMEMBER</span><h3>끝난 뒤에도 남는 것.</h3><p>함께 만든 무대와 팬들의 목소리를 기록합니다.</p></div></section><div class="bottomrow"><button class="textbtn" onclick="archive()">지도와 공연 아카이브 보기 ↗</button><button class="textbtn" onclick="album()">발견한 엔딩 ${collection.length} / 14 ↗</button></div>`}
function mapView(stop){return `<section class="mapcard"><div class="smalllabel">OUR ISLAND / VOYAGE ${stop+1} OF 6</div><div class="minimap"><img src="assets/voyage-map.webp" alt="현재 준비 단계가 표시된 항해 지도">${STOPS.map((x,i)=>`<button title="${x.name}" aria-label="${x.name} 항해 기록" class="mappin ${i===stop?'active':i<stop?'visited':''}" style="left:${x.x}%;top:${x.y}%" onclick="mapNote(${i})">${i<stop?'✓':i+1}</button>`).join('')}</div><div class="stoplist">${STOPS.map((x,i)=>`<span class="${i===stop?'active':''}">${i<stop?'✓':'0'+(i+1)} ${x.name}</span>`).join('')}</div></section>`}
function mapNote(i){modal(`<span class="eyebrow">${STOPS[i].en}</span><h2>${STOPS[i].name}</h2><p>${STOPS[i].note}</p><p>선착장에서 계획을 세우고, 합주실과 광장, 등대를 거쳐 공연장으로 향합니다. 점수를 다시 얻기 위한 이전 선택의 반복은 할 수 없습니다.</p><h3>최근 항해 기록</h3>${S.log.slice(-5).map(x=>`<p class="fine">${esc(x)}</p>`).join('')}`)}
function status(){return `<section class="statuscard"><div class="smalllabel">FOUR VOICES / ONE ISLAND</div><div class="membergrid">${MEMBERS.map((m,i)=>`<div class="member membervoice-${i}"><div class="membertitle"><b>${animalMark(i)}${m.short}</b><span>${m.field}</span><strong style="color:${m.color}">${Math.round(S.sat[i])}</strong></div><div class="bar"><i style="width:${S.sat[i]}%;background:${m.color}"></i></div><div class="energy"><span>${m.part} 체력</span><b>${S.energy[i]}</b></div><div class="bar thin"><i style="width:${S.energy[i]}%;background:${S.energy[i]<20?'#b2604b':'#85937a'}"></i></div></div>`).join('')}</div><div class="audience"><span>관객 ${S.phase==='prep'?'기대':'만족'}도</span><strong>${Math.round(S.audience)}</strong></div><div class="bar"><i style="width:${S.audience}%;background:#b29663"></i></div><div class="resourcegrid"><span>예산<b>${S.budget}</b></span><span>시간<b>${S.time}</b></span><span>흐름<b>${S.cohesion}</b></span></div><button class="textbtn" onclick="setList()">Setlist ${S.set.length}/${MAIN_SONG_COUNT} · 준비 현황 ↗</button></section>`}
function heading(label,title,body='',thought=''){return `<div class="sectionheading"><span class="eyebrow">${label}</span><h2>${title}</h2>${body?`<p>${body}</p>`:''}</div>${thought?thoughtBox(thought):''}`}
function animalMark(i){const m=MEMBER_MOTIFS[i];return `<span class="animalmark" role="img" aria-label="${m.label}">${m.animal}</span>`}
function memberStickers(i){return `<div class="memberstickers" aria-label="${MEMBERS[i].short}의 모티프">${MEMBER_MOTIFS[i].stickers.map(([emoji,label],j)=>`<span class="ministicker sticker-${j}">${emoji==='guitar-black'||emoji==='bass-white'?`<img class="instrumentsticker" src="assets/stickers/${emoji}.svg" alt="${label}">`:`<span class="stickeremoji" role="img" aria-label="${label}">${emoji}</span>`}</span>`).join('')}</div>`}
function thoughtBox(text){return `<aside class="plannerthought" aria-label="기획자의 생각"><span class="thoughtlabel"><i></i>생각…</span><p>${esc(text)}</p></aside>`}
function keywords(items){return `<div class="keywordlist">${(Array.isArray(items)?items:String(items).split(/[·\/]/)).map(x=>x.trim()).filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`}
function metricChips(items){return `<div class="metriclist">${items.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`}
function choice(title,body,meta,handler,disabled=false,index=''){return `<button class="choice" onclick="${handler}" ${disabled?'disabled':''}><span class="choiceindex">${index||'✧'} <i>↗</i></span><h3>${title}</h3>${keywords(body)}<div class="choicemeta">${meta}</div>${disabled?'<span class="unavailable">현재 준비로 선택 불가</span>':''}</button>`}
function prep(){const f=Game.step(S);if(f.type==='song')return songRound(f);if(f.type==='decision'){const d=DECISIONS[f.key],copy=EDITORIAL[f.key];return heading('PRODUCTION MEETING',copy.title,copy.context,copy.thought)+`<div class="choicegrid">${d.options.map((o,i)=>choice(copy.options[i][0],copy.options[i][1],`<div class="effects">${o[3].map((v,j)=>v?`<span style="--effect:${MEMBERS[j].color}">${MEMBERS[j].field} <b>${v>0?'+':''}${v}</b></span>`:'').join('')}</div>`+metricChips([`예산 −${o[4]}`,`시간 −${o[5]}`]),`act('choose','${f.key}',${i})`,S.budget<o[4]||S.time<o[5],'0'+(i+1))).join('')}</div><button class="textbtn fallback" onclick="act('basic')">추가 제작 보류 · 기본 구성 ↗</button>`}if(f.type==='hidden')return hiddenView(f.key);if(f.type==='release')return releaseView();if(f.type==='meeting')return meetingView(f.who);if(f.type==='sns'||f.type==='event')return eventView(f.key);if(f.type==='special')return specialView();if(f.type==='practice')return practiceView();if(f.type==='challenge')return challengeView();if(f.type==='rehearsal')return rehearsalView(f.round);return reviewView()}
function songRound(f){const g=GROUPS[f.group];return heading(`SETLIST / ${String(S.set.length+1).padStart(2,'0')} OF ${MAIN_SONG_COUNT}`,g[0],g[1]+' · 후보 4곡 / 선택 1곡',SONG_THOUGHTS[f.group])+`<div class="songgrid">${Game.candidates(S,f.group).map(x=>songCard(x)).join('')}</div><p class="fine">난이도 /10 · 체력 /100 · 게임용 잠정 수치 / 예찬 솔로의 첫 칸은 바이올린 대신 가창 부담 / 세부 정보는 ↗</p>`}
function songCard(x,encore=false){let item={kind:'track',id:x.id},c=Game.cost(S,item),ok=!encore||(Game.encoreGate(S)&&Game.encoreReady(S,x));return `<article class="songcard"><div class="songtop"><span>${x.kind}</span><button class="circlebtn" aria-label="${esc(x.title)} 상세" onclick="songInfo('${x.id}')">↗</button></div><h3>${esc(x.title)}</h3><div class="songtraits">${keywords(x.traits)}</div><div class="parthead"><span>PART</span><span>난이도</span><span>체력</span></div>${MEMBERS.map((m,i)=>`<div class="partrow"><span>${x.partLabels?.[i]||m.part}</span><div class="diffbars" aria-label="난이도 ${x.diff[i]} /10">${Array.from({length:5},(_,j)=>`<i style="background:${x.diff[i]>j*2?m.color:'#e0d7c5'}"></i>`).join('')}<b>${x.diff[i]}</b></div><strong>−${c[i]}</strong></div>`).join('')}${encore?`<div class="cardnote">${Game.execution(S,item)<65?'합주·기술 준비 부족':!Game.canPlay(S,item)?'체력 또는 공연 시간 부족':'지금 무대로 돌아갈 수 있습니다'}</div>`:''}<button class="selectsong" onclick="act('${encore?'encore':'select'}','${x.id}')" ${ok?'':'disabled'}>${encore?'이 곡으로 한 번 더':'Setlist에 남기기'} <span>＋</span></button></article>`}
function songInfo(id){const x=track(id),item={kind:'track',id},c=Game.cost(S,item);modal(`<span class="eyebrow">TRACK NOTES / ${x.ratingStatus}</span><h2>${esc(x.title)}</h2><p>${esc(x.kind)} · ${esc(x.traits)}</p><table><thead><tr><th>파트</th><th>난이도 /10</th><th>체력 소모</th><th>준비 / 필요</th></tr></thead><tbody>${MEMBERS.map((m,i)=>`<tr><td>${m.short}<small>${x.partLabels?.[i]||m.part}</small></td><td>${x.diff[i]}</td><td>−${c[i]}</td><td>${S.ready[i]} / ${x.diff[i]*4+8}</td></tr>`).join('')}</tbody></table><p class="fine">음원·앨범 크레딧을 참고하되 게임의 무대 버전을 별도로 설정했습니다. 예찬 솔로곡의 첫 번째 칸은 바이올린 연주가 아닌 예찬의 가창 부담입니다. 숫자는 실제 멤버의 기량 평가나 검증된 생리적 측정값이 아닙니다. 원곡과 섬 앙콘 Live의 정밀 분석이 완료되었다고 주장하지 않습니다.</p>${sourceLink(x.source)}${x.group==='solo'?'<p class="fine">‘보컬 중심 무대’는 공연 분류입니다. 발매 아티스트 명의와 같은 뜻이 아닙니다.</p>':''}`)}
function releaseView(){return heading('UNRELEASED / A NEW SHORE','첫 곡은, 다시!','고정 오프닝 + 추가 신곡 최대 2곡','끝에서 다시 출발하는 공연. 첫 곡은 정해졌다… 도시해적의 모험, 록의 열기, 발라드의 여운 중 어떤 장면을 더할까?')+`<div class="openercard"><span class="eyebrow">OPENING / SETLIST 01 · 고정</span><h3>다시!</h3>${keywords(['미발매 오프닝','차기 타이틀 예상'])}<p class="fine">기본 10곡에 포함 · 타이틀곡 여부는 사용자 예상</p></div><div class="newgrid">${OPTIONAL_NEW_TRACKS.map(x=>`<label class="newcard"><input type="checkbox" name="newtracks" value="${x.id}"><span><b>${x.title}</b>${keywords([x.genre,'추가 합주'])}${metricChips(['예산 −3','시간 −8'])}</span></label>`).join('')}</div><p class="fine">다시! + 직접 고른 9곡 = 기본 10곡 / 추가 신곡은 별도 편성 / 261025 공연 설정</p><button class="primary" onclick="confirmRelease()">공개 계획 확정 →</button>`}
function confirmRelease(){const ids=[...document.querySelectorAll('input[name="newtracks"]:checked')].map(x=>x.value);if(ids.length>2){modal('<h2>신곡은 최대 두 곡까지 준비할 수 있습니다.</h2><p>이번 공연에 남길 곡과 다음에 들려줄 곡을 나눠주세요.</p>');return}act('release',ids)}
function meetingView(who){const m=MEMBERS[who],line=[S.picks.concept==='night'?'밤의 섬이라면 소리뿐 아니라 의상이나 빛에도 그 분위기가 있으면 좋겠어.':'곡을 고르는 마음이 무대의 그림에서도 이어지면 좋겠어.',S.set.filter(id=>track(id).group==='power').length>=2?'후반에 달리는 곡들이 있네. 관객이랑 가까이 만날 틈과 숨 돌릴 자리도 같이 남기자.':'음악을 잘 들려주는 것과 함께, 관객이 들어올 순간도 하나 만들고 싶어.',S.picks.arrange==='medley'?'연결을 새로 만들었으니까 그만큼 맞춰볼 시간도 필요해.':'한 곡씩은 좋은데, 이 곡 다음에 왜 저 곡인지도 같이 들렸으면 좋겠어.','무대에서 잘 맞으려면 미리 확인해야 할 게 있어. 조명도 장비도, 어려운 파트의 합도 그냥 넘어가지 말자.'][who];return `<section class="letterpaper membervoice-${who}">${memberStickers(who)}${heading('A VOICE FROM '+m.field.toUpperCase(),`<span class="handname">${m.name}</span>의 메모`,m.field+' / 멤버 회의')}<blockquote>“${line}”</blockquote>${thoughtBox("이 의견을 반영하면 다른 준비에 쓸 시간이 줄어든다. 전부 받을까, 지금 가능한 절충안을 찾을까…?")}<div class="replylist">${[['요구 반영','담당 만족도 +6 · 흐름 +3 / 예산 −1 · 시간 −6'],['절충안','전원 만족도 +1 · 흐름 +2 / 예산 −3 · 시간 −3'],['이번에는 보류','담당 −10 · 다른 멤버 −2 · 흐름 −6 / 자원 유지']].map((o,i)=>`<button onclick="act('meeting',${i})" ${i===0&&(S.time<6||S.budget<1)||i===1&&(S.time<3||S.budget<3)?'disabled':''}><b>${o[0]}</b>${metricChips(o[1].split(/[·\/]/).map(x=>x.trim()))}<span>↗</span></button>`).join('')}</div><p class="fine">게임용 창작 대화 · 실제 발언 인용 아님</p></section>`}
function eventView(key){const e=EVENTS[key],c=EVENT_EDITORIAL[key],costs={memory:[[3,6],[1,2],[0,0]],cute:[[4,5],[0,3],[0,0]],requests:[[2,5],[0,2],[0,0]],technical:[[4,8],[0,0],[0,0]]}[key];return heading(e.label,e.title,e.posts.length?'SNS에서 도착한 요청':'제작 회의 / 현장 점검')+(e.posts.length?`<div class="socialfeed"><div class="feedlabel">ISLAND FEED <span>게임 속 SNS · 실제 게시물 아님</span></div>${e.posts.map((x,i)=>`<div class="post"><span class="postavatar">${i?'✦':'✧'}</span><div><small>@our_island_${i+1} · 기획 기간</small><p>${x}</p><em>♡　↻　답글</em></div></div>`).join('')}</div>`:'')+thoughtBox(c.thought)+`<div class="replylist keywordreplies">${c.options.map((o,i)=>`<button onclick="act('event',${i})" ${S.budget<costs[i][0]||S.time<costs[i][1]?'disabled':''}><b>${o[0]}</b>${keywords(o[1])}${metricChips(c.metrics[i])}<span>↗</span></button>`).join('')}</div>`}
function specialView(){return heading('MEMORIES / SPECIAL STAGE','다시 꺼내볼 특별 무대','공연 기록에서 착안한 무대 · 최대 1개','팬들이 기억하는 장면을 이번 섬에 데려오고 싶다. 난도 높은 무대를 고른다면 전용 연습까지 확보해야 한다…')+`<div class="choicegrid">${SPECIALS.map((x,i)=>choice(SPECIAL_EDITORIAL[x.id][0],SPECIAL_EDITORIAL[x.id][1],metricChips([`예산 −${x.budget}`,`시간 −${x.time}`,...(x.id!=='none'?[`전용 준비 ${x.need}`]:[])]),`act('special','${x.id}')`,S.time<x.time||S.budget<x.budget,'0'+(i+1))).join('')}</div><p class="fine">공연 기록: 아카이브 / 지브리 Medley: 구성·시점 확인 후 추가 검토</p>`}
function practiceView(){const sp=SPECIALS.find(x=>x.id===S.special);if(sp.id==='none')return heading('BAND ROOM','비워둔 시간도 준비가 된다.','기본 합주 · 네 파트 준비도 +3','더하지 않은 무대 덕분에 서로의 소리를 들을 시간이 생겼다. 오늘의 합을 한 번 더 맞춰보자…')+`<button class="primary" onclick="act('practice',0)">기본 합주 →</button>`;return heading('SPECIAL REHEARSAL',sp.title+' · 연습 계획','전용 연습 · 하나 선택','어려운 구간은 무대에서 갑자기 완성되지 않는다. 충분히 맞춰볼까, 핵심 연결만 남길까…?')+`<div class="replylist keywordreplies">${[['전용 합주',['파트별 합','등장 Cue'],['시간 −9','특별 준비 +20']],['핵심 구간',['연결 중심','짧은 점검'],['시간 −4','특별 준비 +9']],['연습 보류',['다음 리허설','준비 부족 위험'],['시간 −0','Music −2','Technic −4']]].map((o,i)=>`<button onclick="act('practice',${i})" ${S.time<[9,4,0][i]?'disabled':''}><b>${o[0]}</b>${keywords(o[1])}${metricChips(o[2])}<span>↗</span></button>`).join('')}</div>`}
function challengeView(){return heading('ISLAND FESTIVAL / CHALLENGE TIME','오늘의 챌린지 릴레이','모든 공연의 고정 중간 코너 · 선곡과 무관하게 진행','한 명씩 등장하는 그 순간, 팬들이 얼마나 좋아할까… 어려운 동작을 욕심낼지, 성공할 수 있는 포인트에 집중할지 정해보자.')+`<div class="challengeassign">${MEMBERS.map((m,i)=>`<label><span class="memberinitial membervoice-${i}" style="--member:${m.color}">${MEMBER_MOTIFS[i].animal}</span><div class="membervoice-${i}"><b class="challengeperson">${m.name}</b><small>현재 체력 ${S.energy[i]}</small></div><select id="challenge-${i}" aria-label="${m.name} 챌린지" onchange="updateChallengePreview()">${Object.entries(CHALLENGE_STYLES).map(([style,label])=>`<optgroup label="${label}">${CHALLENGES.filter(x=>x.style===style).map(x=>`<option value="${x.id}" ${x.id===CHALLENGES[i].id?'selected':''}>${x.name} · ${x.artist}</option>`).join('')}</optgroup>`).join('')}</select><small class="selectedchallenge" id="challenge-note-${i}">${challengeNote(CHALLENGES[i])}</small></label>`).join('')}</div><details class="challengecatalog"><summary>챌린지 전체 보기 · ${CHALLENGES.length}종</summary>${Object.entries(CHALLENGE_STYLES).map(([style,label])=>`<h4>${label}</h4><div class="challengelegend">${CHALLENGES.filter(x=>x.style===style).map(x=>`<span>${x.name} · ${x.artist} / 난도 ${x.difficulty} · 체력 −${x.cost} ${sourceLink(x.source)}</span>`).join('')}</div>`).join('')}</details><div class="replylist keywordreplies">${[['전체 연습',['동작','등장 타이밍','높은 준비도'],['시간 −8','예산 −2']],['포인트 연습',['핵심 안무','컨디션 변수'],['시간 −4']],['즉흥 도전',['현장감','고난도 실패 위험'],['추가 비용 0','Technic −3']]].map((o,i)=>`<button onclick="confirmChallenge(${i})" ${S.time<[8,4,0][i]||S.budget<(i===0?2:0)?'disabled':''}><b>${o[0]}</b>${keywords(o[1])}${metricChips(o[2])}<span>↗</span></button>`).join('')}</div><button class="textbtn fallback" onclick="confirmChallenge(3)">포인트 포즈 릴레이 · 연습 시간 0 / 각 체력 −1 ↗</button><p class="fine">사용자 관람 기록에서 착안 / 배정·결과·수치는 창작 / 음원·안무 영상 없음</p>`}
function challengeNote(x){return `${CHALLENGE_STYLES[x.style]} · 난이도 ${x.difficulty}/10 · 체력 −${x.cost}`}
function updateChallengePreview(){MEMBERS.forEach((m,i)=>{$('#challenge-note-'+i).textContent=challengeNote(CHALLENGES.find(x=>x.id===$('#challenge-'+i).value))})}
function hiddenView(key){const e=HIDDEN_EVENTS[key];return `<section class="hiddenevent"><span class="eyebrow">HIDDEN EVENT / AN UNFOLDED MEMORY</span><div class="hiddenstamp">작은 발견 ✦</div><h2>${e.title}</h2><p class="hiddenstory">${e.story}</p>${thoughtBox(e.thought)}<div class="replylist keywordreplies">${e.options.map((o,i)=>`<button onclick="act('hiddenChoice',${i})" ${i===0&&S.time<2?'disabled':''}><b>${o[0]}</b>${keywords(o[1])}${metricChips(o[2])}<span>↗</span></button>`).join('')}</div><p class="fine">게임 속 창작 장면 · 발견한 이벤트는 항해 기록에 남습니다.</p></section>`}
function confirmChallenge(i){act('challenge',MEMBERS.map((m,j)=>$('#challenge-'+j).value),i)}
function rehearsalView(round){return heading('LIGHTHOUSE / REHEARSAL '+(round+1)+' OF 2','마지막 연습의 우선순위','리허설 · 하나 선택','모든 것을 고칠 시간은 없다. 부족한 합주, 특별 무대, 기술 점검… 지금 가장 큰 위험부터 줄여보자.')+problemList()+`<div class="choicegrid">${[['전체 합주',['기본 합','신곡 합주 해결'],['네 파트 준비도 +11','시간 −10']],['특별 무대 집중',['참여 파트','고부하 구간'],['참여 파트 +17','다른 파트 +4','특별 준비 +4','시간 −10']],['기술·동선 점검',['미점검 항목 해결','전환 Cue'],['네 파트 준비도 +4','시간 −10']],['후반 호흡',['체력 안배','짧은 버전 준비'],['무대별 체력 부담 −1','네 파트 준비도 +3','시간 −5']]].map((o,i)=>choice(o[0],o[1],metricChips(o[2])+(i===1&&S.special==='none'?'<span class="fine">특별 무대 미선택</span>':''),`act('rehearse',${i})`,S.time<[10,10,10,5][i]||(i===1&&S.special==='none'),'0'+(i+1))).join('')}</div><button class="textbtn fallback" onclick="act('noRehearsal')">추가 리허설 생략 · Music −3 / Technic −4 ↗</button>`}
function problemList(){const ps=Game.problems(S);return `<div class="inspection"><div class="smalllabel">CHECK BEFORE SAILING</div>${ps.length?ps.map(x=>`<div class="issue ${x.level}"><span>${x.level==='critical'?'!':'△'}</span><p>${esc(x.text)}</p></div>`).join(''):'<div class="issue clear"><span>✓</span><p>필수 준비 항목을 확인했습니다.</p></div>'}<div class="readiness">${MEMBERS.map((m,i)=>`<span>${m.part}<b>${S.ready[i]} / ${Game.need(S,i)}</b></span>`).join('')}</div></div>`}
function reviewView(){const ps=Game.problems(S),critical=ps.filter(x=>x.level==='critical').length;return heading('THE FINAL CHART','출항 전에, 마지막으로 지도를 봅니다.','중대한 미해결 항목 두 개 이상이면 공연을 강행하지 않습니다. 수정 기회는 두 번이며, 규모를 줄여도 이미 쓴 자원은 돌아오지 않습니다.')+problemList()+`<div class="correction"><span class="smalllabel">마지막 조정 ${2-S.corrections}회 남음</span><button onclick="act('correct','scale')" ${S.corrections>=2?'disabled':''}>특별 연주·큰 효과·Session을 줄인다</button><button onclick="act('correct','focus')" ${S.corrections>=2||S.time<6?'disabled':''}>긴급 합주 · 시간 −6 / 네 파트 +8</button><button onclick="act('correct','hold')" ${S.corrections>=2||!S.news.length?'disabled':''}>신곡 공개를 다음으로 미룬다</button></div><div class="note">${critical>=2?'현재 '+critical+'개의 중대 미해결 항목이 있습니다. 이 상태로 승인하면 준비 실패 엔딩입니다.':'중대 항목 '+critical+'개 · '+(critical?'공연 중 완성도에 영향이 남을 수 있습니다.':'출항 가능한 준비 상태입니다.')}</div><div class="setpaper">${S.set.map((id,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${esc(track(id).title)}</b><small>${id==='new-again'?'OPENING':track(id).soloMember===0?'YECHAN SOLO':track(id).group==='solo'?'VOCAL STAGE':track(id).group==='cute'?'EVENT':''}</small></div>`).join('')}</div><p class="fine">기본 10곡 + 고정 챌린지 코너 + 신곡 ${S.news.length}곡 + ${SPECIALS.find(x=>x.id===S.special).title}. 실제 공연 시간은 무대와 휴식에 따라 증가합니다.</p><button class="primary wide" onclick="act('begin')">${critical>=2?'현재 기획의 결과 확인하기':'최종 승인 · 공연장으로'} ↗</button>`}
function setList(){modal(`<span class="eyebrow">YOUR CUE SHEET</span><h2>현재 공연의 기록</h2><div class="setpaper">${S.set.map((id,i)=>`<div><span>${i+1}</span><b>${esc(track(id).title)}</b></div>`).join('')||'<p>첫 곡을 기다리고 있습니다.</p>'}</div><h3>추가 준비</h3><p>${SPECIALS.find(x=>x.id===S.special).title}<br>신곡: ${S.news.map(id=>track(id).title).join(', ')||'보류'}</p>${problemList()}`)}
function live(){const item=S.queue[S.cursor],x=Game.itemTrack(item),c=Game.cost(S,item),can=Game.canPlay(S,item),short=Game.canPlay(S,item,{short:true});return `<section class="stagepanel"><span class="eyebrow">ON STAGE / ${S.cursor+1} OF ${S.queue.length}</span><div class="moonlight"></div><h2>${esc(x.title)}</h2><p>${liveText(item)}</p><div class="livecost">${MEMBERS.map((m,i)=>`<div><small>${x.partLabels?.[i]||m.part}</small><b>${S.energy[i]} <em>→</em> <strong class="${S.energy[i]<c[i]?'danger':''}">${Math.max(0,S.energy[i]-c[i])}</strong></b><span>체력 −${c[i]}</span></div>`).join('')}</div><div class="liveclock">공연 ${S.elapsed} / ${S.limit}분 · 다음 무대 약 ${Game.duration(S,item)}분 · 준비 기반 완성도 ${Game.execution(S,item)}/100</div><button class="primary" onclick="act('playMain')" ${can?'':'disabled'}>계획한 무대 진행하기 →</button>${!can?`<p class="stagewarning">체력 또는 공연 시간에 여유가 부족합니다. 휴식·축약·종료를 선택해주세요.</p>`:''}<div class="stagealt"><button onclick="act('playMain',{short:true})" ${short?'':'disabled'}>짧은 버전으로 조정</button><button onclick="act('playMain',{crowd:true})" ${S.audienceUsed||!Game.canPlay(S,item,{crowd:true})?'disabled':''}>관객에게 후렴 맡기기 · 1회</button></div></section>${restView()}<button class="textbtn fallback" onclick="confirmWithdraw()">예정된 남은 무대 대신 마지막 인사로 마무리 ↗</button>${S.challengeResult.length?challengeReport():''}`}
function liveText(item){const x=Game.itemTrack(item);if(item.kind==='challenge')return '노래와 악기는 잠시 쉬고, 한 명씩 앞으로! 고른 곡과 상관없이 열리는 아일랜드의 작은 축제입니다. 준비한 춤이 기억날까요?';if(item.kind==='special')return '잠시 두 악기의 소리만 남습니다. 다음 곡을 기다리는 객석의 숨이 조용해집니다.';if(S.cursor===0)return S.picks.arrange==='outro'?'끝을 닮은 선율이 시작이 됩니다. 무대 뒤의 네 사람이 첫 박자를 기다립니다.':'첫 소리가 객석에 닿습니다. 오늘은 여기서, 같은 섬에 모였습니다.';if(x.id==='new-instrument')return '도시해적의 모험 같은 선율이 펼쳐집니다. 보컬은 잠시 쉬고, 악기들이 다음 장면으로 나아갑니다.';if(x.soloMember===0)return S.picks.solo==='piano'?'바이올린을 내려놓은 예찬의 목소리에 빛이 모입니다. 반주는 건반에 맡기고 나머지 멤버는 잠시 숨을 고릅니다.':'예찬이 이번에는 노래로 마음을 전합니다. 따뜻한 왈츠 위에 한 글자씩 목소리를 얹습니다.';if(x.title==='Run To You')return '상엽의 보컬이 무대 한가운데 남습니다. 긴 호흡과 고조되는 감정선을 따라 객석도 조용히 귀를 기울입니다.';if(x.group==='solo')return S.picks.solo==='piano'?'다른 세 파트의 연주는 잠시 쉬고, 건반과 목소리에 빛이 모입니다.':'목소리가 앞에 섭니다. 반주하는 사람과 노래하는 사람의 호흡이 만납니다.';if(x.id==='new-okay')return '아마 괜찮을 너에게. 고른 발라드의 첫 문장에 객석이 조용히 귀를 기울입니다.';if(x.id==='new-shh')return '쉿! 짧은 고요 뒤로 록의 강한 합주가 무대를 채웁니다.';if(x.group==='lyric')return '앞선 환호가 조금씩 잦아듭니다. 다음 문장을 끝까지 들을 수 있는 틈이 생깁니다.';if(x.group==='cute')return S.picks.cute==='props'?'준비한 소품과 짧은 신호. 노래 사이로 웃음이 번집니다.':'서로 눈을 맞추고, 다음 파트를 건넵니다. 조금 장난스러운 섬의 한 장면입니다.';if(x.title==='Ending'&&S.picks.letter==='voices')return '반주를 덜어낸 자리에서 네 사람의 목소리가 이어집니다. 마지막 소리를 서두르지 않습니다.';if(x.title==='Boogie Man'&&S.special==='blind')return '안대를 고쳐 쓰고, 약속한 위치에서 활을 듭니다. 리허설에서 맞췄던 Cue를 기다립니다.';return '다음 곡으로 이어지는 신호를 나눕니다. 준비한 순서가 오늘의 기억이 되어갑니다.'}
function restView(){return `<div class="restbar"><button class="secondary" onclick="act('rest')" ${S.rest>=2||S.restAtCurrent||S.elapsed+3>S.limit?'disabled':''}>멘트·물 한 모금 <small>${2-S.rest}회 남음 · 시간 +3분</small></button><span>체력은 공연과 챌린지에서만 실제로 소모됩니다.<br>솔로·연주곡의 쉬는 파트는 0으로 표시됩니다.</span></div>`}
function confirmWithdraw(){modal('<h2>지금의 마지막 인사를 건넬까요?</h2><p>예정된 곡을 모두 마치기 전 종료하면 ‘마지막 곡에 닿기 전에’ 엔딩으로 이어집니다.</p><button class="primary" onclick="closeModal();act(\'withdraw\')">남은 무대 대신 인사하기</button>')}
function challengeReport(){const words={perfect:'완벽 성공',close:'아슬아슬 성공',recover:'실수 뒤 수습',miss:'짧게 전환'};return `<section class="challengereport"><span class="eyebrow">ISLAND CHALLENGE / THE MOMENT</span><h3>계획과 조금 달랐던, 우리의 축제.</h3>${S.challengeResult.map(r=>`<div class="membervoice-${r.member}"><b>${animalMark(r.member)}${MEMBERS[r.member].short}</b><span>${CHALLENGES.find(x=>x.id===r.id).name}</span><strong class="${['recover','miss'].includes(r.result)?'danger':''}">${words[r.result]}</strong></div>`).join('')}<p class="fine">실수는 교감으로 남을 수도 있지만, 준비 부족의 손실까지 사라지지는 않습니다. 결과는 연습·체력·동작 부담과 작은 현장 변동으로 결정됩니다.</p></section>`}
function farewellView(){return `<section class="farewell"><span class="eyebrow">THE SHORE AFTER THE SHOW</span><div class="stars">✧　　·　　✦　　·</div><h2>마지막 소리가 끝나도,<br>우리는 잠시 여기 있습니다.</h2><p>${S.picks.letter==='letter'?'화면에 편지를 펼칠 시간을 남겼습니다. 빛을 조금 낮추고, 객석이 읽기를 기다립니다.':S.picks.letter==='voices'?'연주가 멎은 자리에 목소리의 흔적이 남습니다. 네 사람이 차례로 객석을 바라봅니다.':S.picks.letter==='crowd'?'마지막 후렴은 객석에서 끝났습니다. 무대 위의 사람들도 그 소리를 듣고 있습니다.':'긴 설명 대신 고른 마지막 노래를 남겼습니다. 나가는 길에도 떠올릴 수 있는 한 장면입니다.'}</p><div class="farewellline"></div><p class="lettercaption">각 멤버의 실제 편지 원문을 확보하지 않아 개인의 말을 대신 쓰지 않았습니다.<br>이 장면은 이번 공연의 손편지·인사·무반주 무대 구성에서 착안한 창작 서술입니다.</p><button class="secondary light" onclick="act('farewell')">무대 뒤의 이야기를 이어서 →</button></section>${S.challengeResult.length?challengeReport():''}`}

function incidentView(){const e=LIVE_INCIDENTS[S.incident];return `<section class="islandincident" aria-live="polite"><div class="incidenttop"><span class="eyebrow">LIVE SIGNAL / ${S.incidentSeen.length+1}</span><span class="incidentpill">${e.badge}</span></div><div class="incidenticon" aria-hidden="true">${e.icon}</div><h2>${e.title}</h2><p class="incidentstory">${e.story}</p>${thoughtBox(e.thought)}<div class="replylist keywordreplies">${e.options.map((o,i)=>`<button onclick="act('incidentChoice',${i})" ${Game.incidentPossible(S,o)?'':'disabled'}><b>${o.title}</b>${keywords(o.tags)}${metricChips(['관객 +'+o.audience,...o.energy.map((v,j)=>v?MEMBERS[j].short+' 체력 '+(v>0?'+':'')+v:'').filter(Boolean),'공연 +'+o.minutes+'분'])}<span>↗</span></button>`).join('')}</div><p class="fine">게임 속 돌발 상황 · 실제 사고·발언 재현 아님 / 시간 제한 없이 선택할 수 있습니다.</p></section>`}
function fatigueView(){return `<section class="fatigueevent"><span class="eyebrow">A VOICE FROM THE SHORE / SPECIAL EVENT</span><div class="crowdvoices">앵콜!　앵콜!　앵콜!</div><h2>팬들이 아직 나가지 않고<br>앵콜을 외치고 있습니다!</h2><p>관객 만족도는 ${S.audience}. 하지만 ${S.energy.map((v,i)=>v===0?MEMBERS[i].short:'').filter(Boolean).join('·')}의 체력은 0입니다.<br>무대 뒤에서도 객석의 목소리가 들립니다. 다시 나갈까요?</p>${thoughtBox("팬들은 아직 이 섬에 머물고 싶어 한다. 더 연주할 체력은 없지만, 그 노래를 들으러 한 번 더 나갈 수는 있지 않을까…?")}<div class="replylist"><button onclick="act('fatigueChoice',true)"><b>한 번 더, 객석으로</b>${keywords(["객석의 후렴","짧은 피날레","추가 연주 없음"])}${metricChips(["관객 +2","체력 회복 없음"])}<span>↗</span></button><button onclick="act('fatigueChoice',false)"><b>오늘의 마지막 인사</b>${keywords(["감사 인사","공연 종료","여운"])}${metricChips(["현재 공연 결과 유지"])}<span>↗</span></button></div><p class="fine">관객 만족도 90 이상 + 한 명 이상 체력 0일 때 등장하는 1회성 이벤트입니다. 본곡 앵콜 횟수와 별도로 기록됩니다.</p></section>`}
function encoreView(){if(Game.fatigueGate(S))return fatigueView();const pool=Game.encorePool(S),page=S.encorePage||0,max=Math.max(1,Math.ceil(pool.length/4)),ready=pool.filter(x=>Game.encoreReady(S,x));return heading('HOMEWARD / ENCORE '+S.encores,'한 번만 더, 이 섬에 머물까요?','더 오래 하는 것만이 좋은 마무리는 아닙니다. 관객의 마음과 네 사람의 상태를 함께 확인합니다.')+`<div class="encorechecks"><span class="${S.sat.every(v=>v>=75)?'ok':''}">전원 만족도 75 이상</span><span class="${S.audience>=80?'ok':''}">관객 만족도 80 이상</span><span class="${ready.length?'ok':''}">가능한 미연주 곡 ${ready.length}곡</span><span>남은 공연 시간 ${S.limit-S.elapsed}분</span></div><button class="primary" onclick="finish()">오늘의 마지막 인사로 마무리 ↗</button>${restView()}${Game.encoreGate(S)?`<div class="songgrid">${pool.slice(page*4,page*4+4).map(x=>songCard(x,true)).join('')}</div><div class="pager"><span>후보 ${page+1} / ${max}</span><button class="secondary" onclick="nextEncorePage()" ${pool.length<=4?'disabled':''}>다른 네 곡 보기 →</button></div>`:'<div class="note">이번 공연에서는 추가 앙코르의 만족도 조건을 충족하지 못했습니다. 본공연을 마친 기록은 그대로 남습니다.</div>'}`}
function nextEncorePage(){S.encorePage=((S.encorePage||0)+1)%Math.max(1,Math.ceil(Game.encorePool(S).length/4));render()}
function finish(){Game.finish(S);remember();render();topPage()}
function result(){const e=Game.ENDINGS[S.final],bad=['rejected','unready','early','rough'].includes(S.final),hidden=['return','challenge','endless','right','century','team','shore'].includes(S.final);return `<section class="result"><div class="resulthead"><span class="eyebrow">${hidden?'HIDDEN MEMORY':bad?'VOYAGE REPORT':'A MEMORY OF OUR ISLAND'}</span><h1>${e[0]}</h1><p>${e[1]}</p></div><div class="resultgrid"><div class="resultticket"><span>RETURN TICKET / ${S.seed.toString().slice(-6)}</span><h2>LUCY<br><i>ISLAND</i></h2><div class="ticketdivider"></div><p>기획 담당자<br><b>${esc(S.name)}</b></p><div class="ticketnums"><span>PLAYED<b>${S.performed.length}</b></span><span>ENCORE<b>${S.encores}</b></span></div><small>다음에 또, 같은 섬에서.</small></div><section class="reportpaper"><span class="eyebrow">FOUR VOICES / AFTER THE SHOW</span>${MEMBERS.map((m,i)=>`<div class="reportmember membervoice-${i}"><span>${animalMark(i)}${m.name}<small>${m.field}</small></span><div class="bar"><i style="width:${S.sat[i]}%;background:${m.color}"></i></div><b>${Math.round(S.sat[i])}</b><em>체력 ${S.energy[i]}</em></div>`).join('')}<div class="reportmetrics"><span>관객 만족도<b>${Math.round(S.audience)}</b></span><span>공연 시간<b>${S.elapsed}분</b></span><span>조정한 무대<b>${S.misses}회</b></span></div><p class="fine">${bad?'놓친 준비와 선택은 아래 기록에서 다시 확인할 수 있습니다.':'같은 곡을 골라도 편곡·호흡·마지막 인사에 따라 다른 공연으로 남습니다.'}</p></section></div>${S.fatigueResolved?`<div class="note"><b>퇴장하지 않은 객석</b><br>${S.fatigueReturn?'악기를 내려놓고 다시 나갔습니다. 마지막 후렴은 팬들이 불렀습니다. 본곡 앵콜과 별도의 피날레로 남았습니다.':'객석의 앵콜에 감사 인사를 전하고, 오늘의 공연을 마무리했습니다.'}</div>`:''}<div class="resultlower"><section class="reportpaper"><span class="eyebrow">${S.performed.length?'PERFORMED SETLIST':'PLANNED SETLIST'}</span><div class="setpaper">${(S.performed.length?S.performed:S.set.map(id=>({kind:'track',id}))).map((it,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${esc(Game.itemTrack(it).title)}</b><small>${it.short?'SHORT':i>=S.queue.length&&S.queue.length?'ENCORE':it.kind==='special'?'SPECIAL':''}</small></div>`).join('')}</div></section><section><span class="eyebrow">OUR ISLAND FEED</span><h2>섬을 떠나는 길에.</h2>${(bad?['기획에서 무엇을 놓쳤는지 다시 적어두기로 했다.','다음에는 마지막까지 함께 갈 호흡부터 남겨두자.']:['오늘 첫 곡 '+track(S.set[0]).title+'. 그 시작이 아직 생각난다.',S.encores>=2?'끝난 줄 알았는데 또 돌아옴. 오늘의 마지막이 몇 번이었지.':'나가는 길인데 아직 마지막 노래가 남아 있는 느낌.',S.challengeResult.some(x=>x.result==='recover')?'챌린지 잠깐 틀리고 서로 보던 그 표정… 준비한 무대랑은 다른 기억이 됐다.':'화려했던 장면도, 조용히 같이 듣던 순간도 오래 남을 것 같다.']).map((t,i)=>`<article class="post resultpost"><span class="postavatar">${i?'✦':'✧'}</span><div><small>@island_memory_${i+1}</small><p>${esc(t)}</p><em>♡　↻　답글</em></div></article>`).join('')}<p class="fine">실제 게시물이 아닌, 플레이 결과에 따라 작성된 게임 속 후기입니다.</p>${S.challengeResult.length?challengeReport():''}<button class="textbtn" onclick="logView()">어떤 선택이 이 결과를 만들었을까? ↗</button></section></div><div class="resultactions"><button class="primary" onclick="S=null;render();topPage()">새로운 항해 시작하기 ↗</button><button class="secondary" onclick="album()">엔딩 컬렉션 ${collection.length}/14</button></div></section>`}
function logView(){modal(`<span class="eyebrow">PRODUCER'S LOG</span><h2>이번 항해의 선택들</h2>${S.log.map((x,i)=>`<div class="logitem"><span>${i+1}</span><p>${esc(x)}</p></div>`).join('')}<h3>최종 점검 기록</h3>${problemList()}`)}
render();
